<%
const 数据 = _.get(variables, 'stat_data', {}) || {};
const 游戏模式 = _.get(数据, '$flag.游戏模式', '剧情模式');

// getwi 是同步世界书读取函数，EJS 中禁止使用 await。
if (游戏模式 === '剧情模式') {
  const 旧日名单 = ['克苏鲁', '哈斯塔', '伊格'];
  const 个人线候选 = [
    ['莫尔迦', '古神列表.莫尔迦.好感度'],
    ['维拉', '古神列表.维拉.好感度'],
    ['斯芬克丝', '古神列表.斯芬克丝.好感度'],
    ['拉维妮亚', '古神列表.拉维妮亚.好感度'],
    ['克茜拉', '古神列表.克茜拉.好感度'],
    ['胧', '古神列表.胧.好感度'],
    ['沈清辞', '重要人物.沈清辞.好感度'],
    ['姜无忧', '重要人物.姜无忧.好感度'],
    ['柳不移', '重要人物.柳不移.好感度'],
    ['萧太薇', '重要人物.萧太薇.好感度'],
    ['白穗', '重要人物.白穗.好感度'],
    ['墨染', '重要人物.墨染.好感度'],
  ];

  const 全部死亡 = 旧日名单.every(名字 => {
    const 条目 = _.get(数据, '旧日支配者列表.' + 名字, {}) || {};
    return 条目.已死亡 === true;
  });
  const 全部高好感 = 旧日名单.every(
    名字 => (Number(_.get(数据, '旧日支配者列表.' + 名字 + '.好感度', -100)) || 0) >= 80,
  );
  const 奈亚好感度 = Number(_.get(数据, '古神列表.奈亚.好感度', 0)) || 0;
  const 已满好感候选 = 个人线候选.filter(([, 路径]) => (Number(_.get(数据, 路径, 0)) || 0) >= 100);

  const 结局状态 = _.get(数据, '$flag.剧情结局', {}) || {};
  const 已记录首位 = String(结局状态.首位满好感角色 || '');
  const 回退首位 = 已满好感候选.length > 0 ? 已满好感候选[0][0] : '';
  const 个人线角色 = String(结局状态.个人线角色 || 已记录首位 || 回退首位);
  let 当前结局 = String(结局状态.当前结局 || '未触发');

  if (当前结局 === '未触发') {
    if (全部死亡) {
      当前结局 = 'A结局';
    } else if (全部高好感) {
      当前结局 = 'B结局';
    } else if (奈亚好感度 >= 80) {
      当前结局 = 'C结局';
    } else if (个人线角色) {
      当前结局 = '共通个人线';
    }
  }

  const 条目映射 = {
    共通个人线: '剧情结局_共通个人线',
    A结局: '剧情结局_A',
    B结局: '剧情结局_B',
    C结局: '剧情结局_C',
  };
  const 条目名 = 条目映射[当前结局];

  if (条目名) {
    let 内容 = String(getwi(条目名));
    if (当前结局 === '共通个人线') {
      内容 = 内容.split('__结局角色__').join(个人线角色 || '首位达到满好感的角色');
    }
    print(内容);

    const 推进轮数 = Number(结局状态.推进轮数) || 0;
    const 周目提示状态 = String(结局状态.周目提示状态 || '未提示');
    if (推进轮数 >= 3 && 周目提示状态 === '未提示') {
      print(getwi('剧情结局_下一周目提示'));
    }
  }
}
%>

